import { Component } from "@angular/core";
import { FormBuilder, FormGroup, Validators, FormArray } from "@angular/forms";
import { FaIconLibrary } from "@fortawesome/angular-fontawesome";
import { fas } from "@fortawesome/free-solid-svg-icons";

@Component({
  selector: "app-course-form",
  templateUrl: "./course-form.component.html",
  styleUrls: ["./course-form.component.scss"],
})
export class CourseFormComponent {
  constructor(public fb: FormBuilder, public library: FaIconLibrary) {
    library.addIconPacks(fas);
  }

  courseForm!: FormGroup;
  availableAuthors: { id: number; name: string }[] = [
    // Initial set of authors
    { id: 1, name: "Author One" },
    { id: 2, name: "Author Two" },
  ];
  courseAuthors: { id: number; name: string }[] = []; // Empty initially

  // Initialize the form
  createCourseForm() {
    this.courseForm = this.fb.group({
      title: ["", [Validators.required, Validators.minLength(2)]],
      description: ["", [Validators.required, Validators.minLength(2)]],
      authors: this.fb.array([]), // FormArray for authors management
      newAuthor: this.fb.group({
        name: [
          "",
          [Validators.minLength(2), Validators.pattern("^[a-zA-Z0-9 ]+$")],
        ],
      }),
      duration: [null, [Validators.required, Validators.min(0)]], // Minutes, must be >= 0
    });
  }

  // Getter for authors FormArray
  get authors(): FormArray {
    return this.courseForm.get("authors") as FormArray;
  }

  // Add an author to Course Authors List
  addAuthorToCourse(author: { id: number; name: string }) {
    const index = this.availableAuthors.findIndex((a) => a.id === author.id);
    if (index !== -1) {
      // Move the author from Available Authors to Course Authors
      this.courseAuthors.push(author);
      this.availableAuthors.splice(index, 1);
    }
  }

  // Remove an author from Course Authors List
  removeAuthorFromCourse(author: { id: number; name: string }) {
    const index = this.courseAuthors.findIndex((a) => a.id === author.id);
    if (index !== -1) {
      // Move the author from Course Authors back to Available Authors
      this.availableAuthors.push(author);
      this.courseAuthors.splice(index, 1);
    }
  }

  // Create a New Author
  createAuthor() {
    const newAuthorName = this.courseForm.get("newAuthor.name")?.value;
    if (newAuthorName.trim() && this.courseForm.get("newAuthor")?.valid) {
      const newAuthor = {
        id: Date.now(), // Generate a unique ID
        name: newAuthorName,
      };
      this.availableAuthors.push(newAuthor); // Add to Available Authors
      this.courseForm.get("newAuthor")?.reset(); // Clear the newAuthor input
    }
  }

  // Submit the form
  onSubmit() {
    if (this.courseForm.valid) {
      console.log("Course form submitted:", this.courseForm.value);
    } else {
      this.courseForm.markAllAsTouched(); // Show all errors
    }
  }
}
<h2>Create / Edit Course</h2>

<form [formGroup]="courseForm" (ngSubmit)="onSubmit()">
  <div class="app-plate">
    <div class="course">
      <!-- Main Information -->
      <h3>Main Info</h3>

      <!-- Title -->
      <div class="form__control">
        <label for="title">Title</label>
        <input
          type="text"
          id="title"
          formControlName="title"
          placeholder="Input title"
        />
        <span
          *ngIf="courseForm.controls['title']?.errors?.['required'] && courseForm.controls['title']?.touched"
          class="text-danger"
        >
          Title is required.
        </span>
        <span
          *ngIf="courseForm.controls['title']?.errors?.['minlength'] && courseForm.controls['title']?.touched"
          class="text-danger"
        >
          Title must be at least 2 characters.
        </span>
      </div>

      <!-- Description -->
      <div class="form__control">
        <label for="description">Description</label>
        <textarea
          id="description"
          formControlName="description"
          placeholder="Input description"
          rows="4"
        ></textarea>
        <span
          *ngIf="courseForm.controls['description']?.errors?.['required'] && courseForm.controls['description']?.touched"
          class="text-danger"
        >
          Description is required.
        </span>
        <span
          *ngIf="courseForm.controls['description']?.errors?.['minlength'] && courseForm.controls['description']?.touched"
          class="text-danger"
        >
          Description must be at least 2 characters.
        </span>
      </div>

      <!-- Authors -->
      <div class="separator"></div>
      <h3>Authors</h3>

      <!-- Add New Author -->
      <div class="form__control">
        <label for="author">New Author</label>
        <input type="text" id="author" placeholder="Input author name" />
        <app-button
          (click)="createAuthor()"
          buttonText="Create Author"
        ></app-button>
        <span
          *ngIf="courseForm.get('newAuthor.name')?.errors?.['minlength'] && courseForm.get('newAuthor.name')?.touched"
          class="text-danger"
        >
          Author name must be at least 2 characters.
        </span>
        <span
          *ngIf="courseForm.get('newAuthor.name')?.errors?.['pattern'] && courseForm.get('newAuthor.name')?.touched"
          class="text-danger"
        >
          Author name should only contain letters and numbers.
        </span>
      </div>

      <!-- Available Authors -->
      <div class="course__authors">
        <h4>Available Authors</h4>
        <ul>
          <li *ngFor="let author of availableAuthors">
            {{ author.name }}
            <app-button
              (click)="addAuthorToCourse(author)"
              buttonText="Add"
            ></app-button>
          </li>
        </ul>
      </div>

      <!-- Course Authors -->
      <div class="course__authors">
        <h4>Course Authors</h4>
        <ul>
          <li *ngFor="let author of courseAuthors">
            {{ author.name }}
            <app-button
              (click)="removeAuthorFromCourse(author)"
              buttonText="Delete"
            ></app-button>
          </li>
        </ul>
      </div>

      <!-- Duration -->
      <div class="separator"></div>
      <h3>Duration</h3>
      <div class="form__control">
        <label for="duration">Duration</label>
        <input
          type="number"
          id="duration"
          formControlName="duration"
          placeholder="Input duration (minutes)"
        />
        <span
          *ngIf="courseForm.controls['duration']?.errors?.['required'] && courseForm.controls['duration']?.touched"
          class="text-danger"
        >
          Duration is required.
        </span>
        <span
          *ngIf="courseForm.controls['duration']?.errors?.['min'] && courseForm.controls['duration']?.touched"
          class="text-danger"
        >
          Duration cannot be less than 0.
        </span>
      </div>

      <!-- Action Buttons -->
      <div class="form__action">
        <app-button [buttonText]="'Submit'"></app-button>
      </div>
    </div>
  </div>
</form>
